/*
 * prog55_connected_components
 *
 * Behaviour (as observed in the original binary):
 *
 *   prog55_connected_components  N  M  u1 v1  u2 v2  …  uM vM
 *
 *   N – number of vertices (0 ≤ N < 8)
 *   M – number of edges   (0 ≤ M < 8)
 *   ui vi – the two endpoints of edge i (0 ≤ ui,vi < N)
 *
 * If any of the above constraints is violated the program prints
 *
 *     INVALID_INPUT
 *
 * (followed by a newline) and exits.
 *
 * Otherwise it builds an undirected adjacency matrix, runs a BFS‑based
 * traversal to discover each connected component and prints the result
 * in exactly the format used by the original binary:
 *
 *   0: {v0,v1,…}
 *   1: {w0,w1,…}
 *   …
 *
 * Vertices inside a component are printed in the order they are visited
 * by the BFS (starting from the smallest still‑unvisited vertex, scanning
 * neighbours in increasing order).  After each component a closing brace
 * and a newline are printed.
 *
 * The program is deliberately limited to at most 7 vertices and 7 edges,
 * matching the limits observed in the decompiled code.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8          /* maximum allowed vertices (0‑7) */
#define MAXE 8          /* maximum allowed edges    (0‑7) */

int main(int argc, char *argv[])
{
    /* ---------- basic argument count ---------- */
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ---------- parse N and M ---------- */
    int N = strtol(argv[1], NULL, 10);   /* number of vertices */
    int M = strtol(argv[2], NULL, 10);   /* number of edges    */

    /* ---------- validate N and M ---------- */
    if (N < 0 || N >= MAXV) {            /* N must be 0‑7 */
        puts("INVALID_INPUT");
        return 0;
    }
    if (M < 0 || M >= MAXE) {            /* M must be 0‑7 */
        puts("INVALID_INPUT");
        return 0;
    }
    if (argc != 3 + 2 * M) {             /* not enough arguments for the edges */
        puts("INVALID_INPUT");
        return 0;
    }

    /* ---------- build adjacency matrix ---------- */
    int adj[MAXV][MAXV] = {0};

    for (int i = 0; i < M; ++i) {
        int u = strtol(argv[3 + 2 * i],     NULL, 10);
        int v = strtol(argv[3 + 2 * i + 1], NULL, 10);

        if (u < 0 || u >= N || v < 0 || v >= N) {
            puts("INVALID_INPUT");
            return 0;
        }
        /* store the undirected edge */
        adj[u][v] = 1;
        adj[v][u] = 1;
    }

    /* ---------- BFS to find connected components ---------- */
    int visited[MAXV] = {0};
    int queue[MAXV];
    int comp_vertices[MAXV][MAXV];   /* component_vertices[comp][pos] */
    int comp_size[MAXV] = {0};
    int comp_cnt = 0;

    for (int start = 0; start < N; ++start) {
        if (visited[start]) continue;          /* already part of a component */

        /* start a new component */
        int qhead = 0, qtail = 0;
        queue[qtail++] = start;
        visited[start] = 1;

        while (qhead < qtail) {
            int v = queue[qhead++];
            comp_vertices[comp_cnt][comp_size[comp_cnt]++] = v;

            /* explore neighbours in increasing order */
            for (int nb = 0; nb < N; ++nb) {
                if (adj[v][nb] && !visited[nb]) {
                    visited[nb] = 1;
                    queue[qtail++] = nb;
                }
            }
        }
        ++comp_cnt;
    }

    /* ---------- output ---------- */
    for (int c = 0; c < comp_cnt; ++c) {
        printf("%d:", c);
        printf(" {");
        for (int i = 0; i < comp_size[c]; ++i) {
            if (i) putchar(',');
            printf("%d", comp_vertices[c][i]);
        }
        putchar('}');
        putchar('\n');
    }

    return 0;
}
